import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"UXS-014 — /explore v2 · navigating the known universe","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/UXS-014.md","filePath":"uxs/UXS-014.md"}'),n={name:"uxs/UXS-014.md"};function s(i,e,l,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="uxs-014-—-explore-v2-·-navigating-the-known-universe" tabindex="-1">UXS-014 — /explore v2 · navigating the known universe <a class="header-anchor" href="#uxs-014-—-explore-v2-·-navigating-the-known-universe" aria-label="Permalink to &quot;UXS-014 — /explore v2 · navigating the known universe&quot;">​</a></h1><blockquote><p>Status · Draft v0.1 Visual fidelity · Spec-only at kickoff; signature moments (boundary crossing, warp, lens toggle) get a prototype / visual anchor gating Slice 0 (per the &quot;visual anchor before UX commit&quot; rule) IA anchor · §explore (extends the existing solar-system route outward) Related PRD · PRD-030 · Related RFC · RFC-032</p></blockquote><h2 id="why-this-uxs-exists" tabindex="-1">Why this UXS exists <a class="header-anchor" href="#why-this-uxs-exists" aria-label="Permalink to &quot;Why this UXS exists&quot;">​</a></h2><p>PRD-030 sets the <em>what/why</em> and RFC-032 the <em>how it&#39;s built</em>; this UXS owns the part that makes or breaks the epic — <strong>how it feels to move through the universe</strong>. The navigation is novel (zoom <em>and</em> warp, nested contexts, physics lenses), and without a pinned interaction model it gets designed ad-hoc in scene code — the chaos we&#39;re explicitly avoiding. This spec is the contract for movement, orientation, selection, transitions, and discovery, on desktop and mobile.</p><h2 id="the-one-rule-you-always-know-where-you-are" tabindex="-1">The one rule: you always know where you are <a class="header-anchor" href="#the-one-rule-you-always-know-where-you-are" aria-label="Permalink to &quot;The one rule: you always know where you are&quot;">​</a></h2><p>With teleporting instead of continuous travel, orientation is the scarcest resource. Every screen carries a <strong>breadcrumb / &quot;you are here&quot;</strong>: <code>Solar System › Orion Spur › Milky Way › Local Group</code>. It&#39;s always visible, always clickable (each crumb warps back to that context). This is non-negotiable — it&#39;s what keeps discovery from becoming disorientation.</p><h2 id="navigation-model" tabindex="-1">Navigation model <a class="header-anchor" href="#navigation-model" aria-label="Permalink to &quot;Navigation model&quot;">​</a></h2><ul><li><strong>Zoom within a context</strong> — the existing /explore camera controls, unchanged. Scroll/pinch out keeps pulling back.</li><li><strong>The boundary crossing (the signature moment)</strong> — as you zoom out past the Kuiper/Oort, the solar system smoothly <strong>collapses to a single luminous dot</strong> and the real nearby-star field <strong>fades in around it</strong>, re-based into the Neighborhood context. Continuous, legible, cinematic — no hard cut. This is the emotional core of v2; it gets a prototype before code.</li><li><strong>Warp between contexts</strong> — beyond the Neighborhood, you don&#39;t crawl through empty black. Click a pin (a galaxy, the galactic center) → a <strong>1–2 s cinematic warp</strong> with a caption that <em>teaches the distance</em> (&quot;warping 4.24 light-years to Proxima Centauri…&quot;, &quot;2.5 million years to Andromeda…&quot;). The warp motivates from a real click and always lands you oriented (breadcrumb updates, target framed).</li><li><strong>Two doors in</strong> — (a) <strong>wander</strong> and stumble on objects in the dark (the discovery joy), and (b) <strong>jump</strong> straight from a deep-sky gallery photo or an object index via <code>?goto=&lt;id&gt;</code> (browse-as-collection). Same objects, two ways.</li></ul><h2 id="selecting-understanding-an-object" tabindex="-1">Selecting &amp; understanding an object <a class="header-anchor" href="#selecting-understanding-an-object" aria-label="Permalink to &quot;Selecting &amp; understanding an object&quot;">​</a></h2><p>Click any star / planet / deep-sky object → the existing <strong>Panel</strong> opens (bottom-sheet mobile / right drawer desktop), with tactical detail from real data: name, distance (&quot;light left in…&quot;), type/spectral class, and — for exoplanet systems — the full per-planet treatment mirroring our solar-system planets. Selection styling + hover mirror the current /explore conventions. Everything localized (i18n) like /science; every fact carries provenance.</p><h2 id="lenses-physics-overlays" tabindex="-1">Lenses (physics overlays) <a class="header-anchor" href="#lenses-physics-overlays" aria-label="Permalink to &quot;Lenses (physics overlays)&quot;">​</a></h2><p>Reuse the <strong>Science-Lens</strong> control already on /explore. Lenses are toggles on the current scene, not separate screens: <strong>curvature</strong> (spacetime grid warps around mass — labeled as an analogy), <strong>time</strong> (dilation readout + light-travel-time), <strong>causality</strong> (light-cone spheres), <strong>property-space</strong> (re-projects the same star field onto physical axes — the flyable Hertzsprung-Russell diagram). Only offer lenses meaningful in the active context. A lens never hides the breadcrumb or the exit.</p><h2 id="culture-doors" tabindex="-1">Culture doors <a class="header-anchor" href="#culture-doors" aria-label="Permalink to &quot;Culture doors&quot;">​</a></h2><p>Optional overlay (off by default) that attaches a story card to a real object (Vega → <em>Contact</em>, Gargantua → <em>Interstellar</em>, Kepler-16b → Tatooine). Clearly badged <strong>fiction over fact</strong> — the real object&#39;s science stays primary; the story is a labeled layer. Entry point for later messaging/discussion.</p><h2 id="responsive-performance-desktop-mobile" tabindex="-1">Responsive &amp; performance (desktop + mobile) <a class="header-anchor" href="#responsive-performance-desktop-mobile" aria-label="Permalink to &quot;Responsive &amp; performance (desktop + mobile)&quot;">​</a></h2><ul><li>The <strong>device budget</strong> (RFC-032 C-C) governs dot density: the journey is identical on phone and desktop, the <em>count</em> adapts. Core navigation (zoom, warp, select, breadcrumb) is full parity everywhere.</li><li>Heaviest lenses/shaders (gravitational lensing) may be <strong>desktop-first with a graceful mobile tier</strong> — never a hard &quot;unsupported,&quot; always a legible fallback.</li><li>Touch: pinch-zoom for within-context, tap-a-pin for warp; the breadcrumb is a tappable 44px target row.</li></ul><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><p>Extends the existing /explore a11y (RFC-031): the object index is keyboard-reachable (the DOM &quot;mirror&quot; pattern — every selectable object in a list, <code>?goto=</code> works without the canvas), breadcrumb is keyboard-navigable, warps announce their destination to screen readers, reduced-motion shortens/skips the warp cinematics and the boundary-collapse animation.</p><h2 id="signature-moments-that-get-a-visual-anchor-before-build" tabindex="-1">Signature moments that get a visual anchor before build <a class="header-anchor" href="#signature-moments-that-get-a-visual-anchor-before-build" aria-label="Permalink to &quot;Signature moments that get a visual anchor before build&quot;">​</a></h2><ol><li><strong>Boundary crossing</strong> — Sun → one dot among real stars.</li><li><strong>A warp</strong> — the cinematic hop + distance caption + re-orientation.</li><li><strong>A lens toggle</strong> — the map re-rendered through physics (curvature grid).</li></ol><p>These three are prototyped/mocked on real screenshots and gated on Marko&#39;s approval before the corresponding slice ships.</p>',21)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
